{
  "name": "claude-accounts-usage",
  "version": "0.3.0",
  "description": "OpenCode TUI plugin to view multi-account Claude and ChatGPT subscription usage and switch the active account. Coexists with @ex-machina/opencode-anthropic-auth and OpenCode built-in codex auth.",
  "type": "module",
  "license": "MIT",
  "author": "vince.dai",
  "homepage": "https://github.com/Daiwenxi798673133/claude-accounts-usage#readme",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/Daiwenxi798673133/claude-accounts-usage.git"
  },
  "bugs": {
    "url": "https://github.com/Daiwenxi798673133/claude-accounts-usage/issues"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "claude",
    "anthropic",
    "usage",
    "quota",
    "multi-account",
    "tui",
    "openai",
    "chatgpt",
    "codex"
  ],
  "exports": {
    ".": {
      "import": "./dist/tui.js"
    },
    "./tui": {
      "import": "./dist/tui.js"
    }
  },
  "files": [
    "dist",
    "tui.tsx",
    "src",
    "!src/**/*.test.ts",
    "README.md",
    "LICENSE"
  ],
  "engines": {
    "opencode": ">=1.3.13",
    "node": ">=22"
  },
  "publishConfig": {
    "access": "public"
  },
  "scripts": {
    "build": "bun run scripts/build.ts",
    "typecheck": "tsc --noEmit",
    "prepublishOnly": "tsc --noEmit && bun run build"
  },
  "dependencies": {
    "@opencode-ai/plugin": "^1.17.4",
    "@opentui/solid": "^0.4.1",
    "solid-js": "^1.9.13"
  },
  "devDependencies": {
    "@types/bun": "^1.3.14",
    "@types/node": "^25.9.3",
    "typescript": "^5.9.3"
  }
}
